const entries = [];
let limit = 0;
let listener = null;

function add(name, plugin) {
  entries.push({ name, plugin });
  if (listener !== null) listener(name);
}

export class Plugin {
  constructor(label) {
    this.label = label;
  }
}

/** A class whose construction registers the instance. */
export class Entry {
  constructor(name) {
    this.name = name;
    add(name, new Plugin(name));
  }
}

export const alpha = new Plugin("alpha");
export const beta = new Plugin("beta");

export const registry = {
  /** How many times grow() ran: a data member, which a snapshot records. */
  size: 0,
  register(name, plugin) {
    add(name, plugin);
  },
  make(label) {
    return new Plugin(label);
  },
  configure(options) {
    limit = options.limit;
    for (const tag of options.tags ?? []) add(`tag:${tag}`, new Plugin(tag));
  },
  setLimit(n) {
    limit = n;
  },
  limit() {
    return limit;
  },
  count() {
    return entries.length;
  },
  list() {
    return entries.map((entry) => `${entry.name}=${entry.plugin.label}`).join(",");
  },
  grow() {
    registry.size++;
  },
  loud(name) {
    console.log(`plug-kit: registering ${name}`);
    add(name, new Plugin(name));
  },
  fail(message) {
    throw new Error(message);
  },
  onRegister(callback) {
    listener = callback;
  },
  failLater(message) {
    return Promise.reject(new Error(message));
  },
};
